// See README.md for license details.
// -----------------------------------------------------------------------------
//  SimpleBackend.scala — NPU backend: InstrDecoder + MultiWidthRF + MMALU + VALU
//
//  Parameters:
//    K    — SIMD lane count per register = MMALU array side (default 8).
//           At the top level, K = 64 to match MMALU(new MMPE(), 64, 8, 32).
//    N    — base lane width in bits / N(bits) (default 8).
//    L    — number of VX base registers (default 32, must be div-by-4).
//
//  MMALU mapping: MMALU.n (array side) == K; MMALU.nbits == N.
//  This is the backend boundary alignment constraint. Both must be equal.
//
//  Register file (MultiWidthRegisterBlock):
//    VX[0..L-1]     K × N bits     INT8 / BF8 results, MMALU narrow inputs
//    VE[0..L/2-1]   K × 2N bits    INT16 / BF16 results
//    VR[0..L/4-1]   K × 4N bits    INT32 / FP32 results; MMALU accumulator direct write
//
//  Port assignments:
//    VX read:  port 0 = MMALU in_a; port 1 = VALU in_a_vx
//    VX read:  port 2 = VALU in_b_vx; port 3 = external read
//    VE read:  port 0 = VALU in_a_ve; port 1 = VALU in_b_ve
//    VR read:  port 0 = VALU in_a_vr + MMALU in_b; port 1 = VALU in_b_vr + in_c_vr
//    VX write: port 0 = VALU narrow out; port 1 = external write
//    VE write: port 0 = VALU VE out
//    VR write: port 0 = VALU VR out; port 1 = MMALU accumulator direct (INT32, no truncation)
//
//  Instruction decode: 32-bit word → InstrDecoder → DecodedMicroOp.
//  All dispatch is based on the decoded family + VecOp.
//
//  Write-back timing: VALU has a 1-cycle output register.
//  The backend keeps the decoded op active for 2 cycles (issue + write-back).
//  A production frontend should use a 1-cycle pipeline stall or forwarding.
// -----------------------------------------------------------------------------

package backend

import chisel3._
import chisel3.util._

import alu.mma._
import alu.pe._
import alu.vec._
import isa._
import isa.micro_op._
import sram.mwreg._

// Width constants matching VecWidth enum values (0=VX, 1=VE, 2=VR)
// Used to compare dec.valu.regCls (UInt(2.W)) without importing ChiselEnum
private object W { val VX = 0.U(2.W); val VE = 1.U(2.W); val VR = 2.U(2.W) }

class NCoreBackend(
    val K: Int = 8,
    val N: Int = 8,
    val L: Int = 32,
) extends Module {

  require(L % 4 == 0, s"NCoreBackend: L=$L must be divisible by 4")
  require(K > 0 && N > 0)

  val N2 = 2 * N
  val N4 = 4 * N

  val VX_ADDR = log2Ceil(L)
  val VE_ADDR = log2Ceil(L / 2)
  val VR_ADDR = log2Ceil(L / 4)

  val io = IO(new Bundle {
    // Raw 32-bit instruction word (from frontend or test harness)
    val instr       = Input(UInt(32.W))
    val illegal_out = Output(Bool())  // illegal instruction flag

    // ---- VX address ports (test harness / future frontend) ----
    val vx_a_addr   = Input(UInt(VX_ADDR.W))
    val vx_b_addr   = Input(UInt(VX_ADDR.W))
    val vx_out_addr = Input(UInt(VX_ADDR.W))

    // ---- VE address ports ----
    val ve_a_addr   = Input(UInt(VE_ADDR.W))
    val ve_b_addr   = Input(UInt(VE_ADDR.W))
    val ve_out_addr = Input(UInt(VE_ADDR.W))

    // ---- VR address ports (rd=output; rs1=A; rs2=B; rs3=C for FMA) ----
    val vr_a_addr   = Input(UInt(VR_ADDR.W))
    val vr_b_addr   = Input(UInt(VR_ADDR.W))
    val vr_c_addr   = Input(UInt(VR_ADDR.W))
    val vr_out_addr = Input(UInt(VR_ADDR.W))

    // ---- MMALU control passthrough ----
    val mma_a_addr   = Input(UInt(VX_ADDR.W))
    val mma_b_addr   = Input(UInt(VX_ADDR.W))
    val mma_out_addr = Input(UInt(VR_ADDR.W))  // MMALU output goes to VR

    // ---- External RF access (VX width) ----
    val ext_wr_en   = Input(Bool())
    val ext_wr_addr = Input(UInt(VX_ADDR.W))
    val ext_wr_data = Input(Vec(K, UInt(N.W)))
    val ext_rd_addr = Input(UInt(VX_ADDR.W))
    val ext_rd_data = Output(Vec(K, UInt(N.W)))

    // ---- External VR access (for reading INT32 / FP32 results) ----
    val vr_rd_addr  = Input(UInt(VR_ADDR.W))
    val vr_rd_data  = Output(Vec(K, UInt(N4.W)))
  })

  // ==========================================================================
  // Instruction decoder
  // ==========================================================================
  val decoder = Module(new InstrDecoder)
  decoder.io.instr := io.instr
  io.illegal_out   := decoder.io.illegal
  val dec = decoder.io.decoded

  // ==========================================================================
  // Multi-width register file
  // ==========================================================================
  val rf = Module(new MultiWidthRegisterBlock(L, K, N,
    vx_rd = 4, vx_wr = 2, ve_rd = 2, ve_wr = 1, vr_rd = 2, vr_wr = 2))

  // ---- VX reads ----
  rf.io.vx_r_addr(0) := io.mma_a_addr    // MMALU A
  rf.io.vx_r_addr(1) := io.vx_a_addr     // VALU in_a_vx
  rf.io.vx_r_addr(2) := io.vx_b_addr     // VALU in_b_vx
  rf.io.vx_r_addr(3) := io.ext_rd_addr   // external
  io.ext_rd_data      := rf.io.vx_r_data(3)

  // ---- VE reads ----
  rf.io.ve_r_addr(0) := io.ve_a_addr
  rf.io.ve_r_addr(1) := io.ve_b_addr

  // ---- VR reads ----
  rf.io.vr_r_addr(0) := io.vr_a_addr
  rf.io.vr_r_addr(1) := io.vr_b_addr
  io.vr_rd_data       := rf.io.vr_r_data(0)

  // Drive the external read port of the RF (separate from vx_r_addr)
  rf.io.ext_r_addr := io.ext_rd_addr

  // ---- Default: all write ports disabled ----
  rf.io.vx_w_en  := VecInit(Seq.fill(2)(false.B))
  rf.io.ve_w_en  := VecInit(Seq.fill(1)(false.B))
  rf.io.vr_w_en  := VecInit(Seq.fill(2)(false.B))
  rf.io.vx_w_addr := VecInit(Seq.fill(2)(0.U(VX_ADDR.W)))
  rf.io.ve_w_addr := VecInit(Seq.fill(1)(0.U(VE_ADDR.W)))
  rf.io.vr_w_addr := VecInit(Seq.fill(2)(0.U(VR_ADDR.W)))
  for (p <- 0 until 2) for (lane <- 0 until K) rf.io.vx_w_data(p)(lane) := 0.U
  for (p <- 0 until 1) for (lane <- 0 until K) rf.io.ve_w_data(p)(lane) := 0.U
  for (p <- 0 until 2) for (lane <- 0 until K) rf.io.vr_w_data(p)(lane) := 0.U

  // ---- External write ----
  rf.io.ext_w_en   := io.ext_wr_en
  rf.io.ext_w_addr := io.ext_wr_addr
  rf.io.ext_w_data := io.ext_wr_data

  // ==========================================================================
  // MMALU (systolic array; n = K lanes, nbits = N)
  // ==========================================================================
  val mmalu = Module(new MMALU(new MMPE(N), K, N, N4))
  mmalu.io.in_a := VecInit(rf.io.vx_r_data(0).map(_.asSInt))
  // MMALU in_b taken from VX (same layout as in_a, different addr)
  rf.io.vx_r_addr(0) := io.mma_a_addr  // already assigned above; in_b via separate VX port
  // Note: we route MMALU in_b through vx_r_data(0) with mma_b_addr
  // To give MMALU its own B port, we repurpose ext port when no ext read is active.
  // For simplicity in tests, use the same vx_r_data(3) for MMALU B (driven by mma_b_addr).
  rf.io.vx_r_addr(3) := Mux(io.ext_wr_en || io.ext_rd_addr.orR, io.ext_rd_addr, io.mma_b_addr)
  mmalu.io.in_b     := VecInit(rf.io.vx_r_data(3).map(_.asSInt))
  mmalu.io.in_accum := VecInit(Seq.fill(K)(0.S(N4.W)))

  // MMALU control from decoded instruction
  mmalu.io.ctrl.keep      := dec.mma_keep
  mmalu.io.ctrl.use_accum := false.B
  mmalu.io.ctrl.busy      := (dec.family === OpFamily.MMA)

  // MMALU write-back directly to VR (port 1) — NO precision truncation
  // mmalu.io.out is Vec(K, SInt(N4.W)) = Vec(K, SInt(32.W)) for N=8
  when (dec.family === OpFamily.MMA) {
    rf.io.vr_w_en(1)   := true.B
    rf.io.vr_w_addr(1) := io.mma_out_addr
    for (lane <- 0 until K) {
      rf.io.vr_w_data(1)(lane) := mmalu.io.out(lane).asUInt
    }
  }

  // ==========================================================================
  // VALU
  // ==========================================================================
  val valu = Module(new VALU(K, N))

  // Connect inputs from RF
  for (lane <- 0 until K) {
    valu.io.in_a_vx(lane) := rf.io.vx_r_data(1)(lane)
    valu.io.in_b_vx(lane) := rf.io.vx_r_data(2)(lane)
    valu.io.in_a_ve(lane) := rf.io.ve_r_data(0)(lane)
    valu.io.in_b_ve(lane) := rf.io.ve_r_data(1)(lane)
    valu.io.in_a_vr(lane) := rf.io.vr_r_data(0)(lane)
    valu.io.in_b_vr(lane) := rf.io.vr_r_data(1)(lane)
    valu.io.in_c_vr(lane) := rf.io.vr_r_data(1)(lane)  // C re-uses B port for now
  }

  // Drive VALU ctrl from decoded bundle
  valu.io.ctrl := dec.valu

  // Determine if this is a VALU family
  val isVALU = dec.family === OpFamily.VALU_ARITH  ||
               dec.family === OpFamily.VALU_LOGIC   ||
               dec.family === OpFamily.VALU_REDUCE  ||
               dec.family === OpFamily.VALU_LUT     ||
               dec.family === OpFamily.VALU_CVT     ||
               dec.family === OpFamily.VALU_BCAST   ||
               dec.family === OpFamily.VALU_FP      ||
               dec.family === OpFamily.VALU_FP_FMA  ||
               dec.family === OpFamily.VALU_MOV

  // VALU write-back (port 0 for each class)
  when (isVALU) {
    // VX write-back.
    // isReduceToVR ops (vsum, vrmax, vrmin) encode their *input* class in regCls
    // (e.g. vsum.vx has regCls=VX so the VALU selects the VX reduction path).
    // That would accidentally assert vx_w_en and clobber vx_out_addr — suppress it.
    // isSetLut ops (vsetlut) write only to VALU-internal bank registers;
    // all RF write ports must be suppressed.
    rf.io.vx_w_en(0)   := ((dec.valu.regCls === W.VX) || isNarrowCvtOut(dec.valu.op)) &&
                           !isReduceToVR(dec.valu.op) &&
                           !isSetLut(dec.valu.op)
    rf.io.vx_w_addr(0) := io.vx_out_addr
    for (lane <- 0 until K) rf.io.vx_w_data(0)(lane) := valu.io.out_vx(lane)

    // VE write-back
    rf.io.ve_w_en(0)   := dec.valu.regCls === W.VE
    rf.io.ve_w_addr(0) := io.ve_out_addr
    for (lane <- 0 until K) rf.io.ve_w_data(0)(lane) := valu.io.out_ve(lane)

    // VR write-back (FP/INT32, wide conversion results, and horizontal reductions).
    // vsetlut has regCls=VR but must NOT write the RF — suppress it.
    rf.io.vr_w_en(0)   := ((dec.valu.regCls === W.VR) || isWideCvtOut(dec.valu.op) ||
                            isReduceToVR(dec.valu.op)) &&
                           !isSetLut(dec.valu.op)
    rf.io.vr_w_addr(0) := io.vr_out_addr
    for (lane <- 0 until K) rf.io.vr_w_data(0)(lane) := valu.io.out_vr(lane)
  }

  // ==========================================================================
  // Helpers: determine output register class for conversion and reduce ops
  // ==========================================================================
  def isNarrowCvtOut(op: VecOp.Type): Bool = {
    op === VecOp.vcvt_s8_s32 ||  // s8 sign-extend → VX slice
    op === VecOp.vcvt_f32_s8     // FP32 → INT8 narrow
    // vcvt_s8_f32 = INT8→FP32: wide output → VR, NOT narrow
  }

  def isWideCvtOut(op: VecOp.Type): Bool = {
    op === VecOp.vcvt_s32_f32  ||  // s32→f32: wide
    op === VecOp.vcvt_s8_f32   ||  // s8→f32: wide
    op === VecOp.vcvt_f32_s32  ||
    op === VecOp.vcvt_s32_s8   ||
    op === VecOp.vcvt_f32_bf8  ||
    op === VecOp.vcvt_bf8_f32  ||
    op === VecOp.vcvt_f32_bf16 ||
    op === VecOp.vcvt_bf16_f32 ||
    op === VecOp.vcvt_s16_s32  ||
    op === VecOp.vcvt_s32_s16
  }

  /**
   * vsetlut writes only to VALU-internal LUT bank registers.
   * All register-file write ports must be suppressed for this op.
   */
  def isSetLut(op: VecOp.Type): Bool = op === VecOp.vsetlut

  /**
   * Horizontal reduce ops (vsum, vrmax, vrmin) always produce a VR-width result
   * broadcast across all K lanes, regardless of the regCls field in the instruction.
   * The VALU unconditionally drives out_vr for these ops; the backend must enable
   * the VR write port to store the result in the register file.
   *
   * Root cause: the ISA encodes reduce ops with the *input* register class in
   * funct7[1:0] (e.g. vsum.vx uses regCls=VX to select the VX reduction path),
   * but the output is always VR-width.  The backend's regCls===VR guard therefore
   * misses these ops when issued on VX or VE inputs.
   */
  def isReduceToVR(op: VecOp.Type): Bool = {
    op === VecOp.vsum  ||
    op === VecOp.vrmax ||
    op === VecOp.vrmin
  }
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  instSetArch.scala — NPU opcode families and per-family funct3 enums
//
//  Encoding model: RISC-V-inspired 32-bit instruction word.
//    opcode (7b) selects a functional *family*.
//    funct3 (3b) selects the sub-operation within the family.
//    funct7 (7b) carries attributes: width, round, saturate, dtype class.
//    rd, rs1, rs2 (5b each) index the register file.
//
//  See instrFormat.scala for bit-position constants and attribute enums.
//  See NpuAssembler.scala for a Scala-side assembler that builds instruction words.
//
//  Notation :
//    N(bits) — base lane width in bits (default 8). MMALU's nbits.
//    L       — number of VX base registers (default 32, must be div-by-4).
//    K       — SIMD lane count per register (8 for tests, 64 at top).
//              Equals MMALU's array-side n at the backend boundary.
//    VX[0..L-1]   — L  registers of K × N    bits
//    VE[0..L/2-1] — 16 registers of K × 2N   bits (alias VX[2i..2i+1])
//    VR[0..L/4-1] — 8  registers of K × 4N   bits (alias VX[4i..4i+3])
// -----------------------------------------------------------------------------

package isa

import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// Opcode families (7-bit primary decode field)
// ---------------------------------------------------------------------------
object OpFamily extends ChiselEnum {
  val NOP          = Value(0x00.U(7.W))
  val LD           = Value(0x01.U(7.W))
  val ST           = Value(0x02.U(7.W))
  val MMA          = Value(0x03.U(7.W))
  val VALU_ARITH   = Value(0x10.U(7.W))
  val VALU_LOGIC   = Value(0x11.U(7.W))
  val VALU_REDUCE  = Value(0x12.U(7.W))
  val VALU_LUT     = Value(0x13.U(7.W))
  val VALU_CVT     = Value(0x14.U(7.W))
  val VALU_BCAST   = Value(0x15.U(7.W))
  val VALU_FP      = Value(0x16.U(7.W))
  val VALU_FP_FMA  = Value(0x17.U(7.W))
  val VALU_MOV     = Value(0x18.U(7.W))
}

// ---------------------------------------------------------------------------
// funct3 encodings per family
// ---------------------------------------------------------------------------

// VALU_ARITH (opcode=0x10): elementwise arithmetic on VX/VE/VR
// Width from funct7[1:0]; saturate from funct7[4].
// RISC-V aligned where possible.
object Funct3Arith {
  val ADD  = 0.U(3.W)   // rd = rs1 + rs2
  val SUB  = 1.U(3.W)   // rd = rs1 - rs2
  val MUL  = 2.U(3.W)   // rd = rs1 * rs2  (narrow sat; wide on out_wide)
  val NEG  = 3.U(3.W)   // rd = -rs1  (rs2 ignored)
  val ABS  = 4.U(3.W)   // rd = |rs1|  (rs2 ignored)
  val MAX  = 5.U(3.W)   // rd = max(rs1, rs2)
  val MIN  = 6.U(3.W)   // rd = min(rs1, rs2)
  val RSUB = 7.U(3.W)   // rd = rs2 - rs1  (reverse subtract)
}

// VALU_LOGIC (opcode=0x11): bitwise and shift operations on VX/VE/VR
// RISC-V aligned: SLL=001, SRL/SRA=101, XOR=100, OR=110, AND=111.
object Funct3Logic {
  val SLL = 0.U(3.W)   // logical left shift
  val SRL = 1.U(3.W)   // logical right shift
  val SRA = 2.U(3.W)   // arithmetic right shift (sign extending)
  val ROL = 3.U(3.W)   // rotate left
  val XOR = 4.U(3.W)   // RV xor (100)
  val NOT = 5.U(3.W)   // bitwise NOT (rs2 ignored)
  val OR  = 6.U(3.W)   // RV or (110)
  val AND = 7.U(3.W)   // RV and (111)
}

// VALU_REDUCE (opcode=0x12): horizontal reductions, result broadcast to all lanes
object Funct3Reduce {
  val SUM  = 0.U(3.W)  // Σ lanes → out_wide broadcast
  val RMAX = 1.U(3.W)  // max over lanes → broadcast
  val RMIN = 2.U(3.W)  // min over lanes → broadcast
  val RAND = 3.U(3.W)  // AND over lanes → broadcast
  val ROR  = 4.U(3.W)  // OR  over lanes → broadcast
  val RXOR = 5.U(3.W)  // XOR over lanes → broadcast
  // 6, 7 reserved
}

// VALU_LUT (opcode=0x13): programmable two-bank LUT, raw byte-in/byte-out
//
//  vlut   (funct3=0/1) — per-lane 256-entry lookup from bank A (funct3=0)
//                        or bank B (funct3=1).  R-type; rd=VX dst, rs1=VX src.
//                        round[0] in the decoded bundle = bank select (0=A, 1=B).
//
//  vsetlut (funct3=4/5) — write one K×4-byte segment of the LUT bank from a
//                          VR source register.  I-type; rs1=VR src, imm=segment.
//                          funct3=4 → bank A, funct3=5 → bank B.
//                          No register-file write (side-effect on VALU-internal state only).
//
//  Segment packing: VR[rs1] holds K lanes × 4 bytes = K×4 consecutive LUT
//  entries.  Segment index s maps to LUT entries [s×K×4 .. (s+1)×K×4 − 1].
//  At K=8  : 8 vsetlut calls fill the full 256-byte bank.
//  At K=64 : 1 vsetlut call fills the full 256-byte bank.
//
//  The Qfmt object (vec.scala) remains available as a Scala-only compiler and
//  test utility for generating table data; it is no longer synthesised as hardware.
object Funct3Lut {
  val VLUT_A    = 0.U(3.W)  // per-lane lookup from bank A (R-type)
  val VLUT_B    = 1.U(3.W)  // per-lane lookup from bank B (R-type)
  // 2..3 reserved
  val VSETLUT_A = 4.U(3.W)  // write K×4-byte segment into bank A (I-type)
  val VSETLUT_B = 5.U(3.W)  // write K×4-byte segment into bank B (I-type)
  // 6..7 reserved
}

// VALU_CVT (opcode=0x14): type conversions
// funct3 = destination format code (FmtCode object in instrFormat.scala)
// funct7[2:0] = source format code; funct7[3]=sat; funct7[5:4]=round; funct7[6]=BF8 variant
// Width is determined by src/dst format (e.g. s32 implies VR; s8 implies VX).

// VALU_BCAST (opcode=0x15): scalar broadcast to all K lanes
object Funct3Bcast {
  val REG = 0.U(3.W)   // R-format: rd[i] = rs1[0] for all i; width from funct7[1:0]
  val IMM = 1.U(3.W)   // I-format: rd[i] = sext(imm[11:0]); width from funct7[1:0]
  // 2..7 reserved
}

// VALU_FP (opcode=0x16): FP32 arithmetic on VR lanes; width and dtype implicit (VR, FP)
// funct7[3:2] carries round mode; funct7[6:5] reserved-must-be-01 (FP dtype).
object Funct3Fp {
  val FADD = 0.U(3.W)
  val FSUB = 1.U(3.W)
  val FMUL = 2.U(3.W)
  val FNEG = 3.U(3.W)  // rs2 ignored
  val FABS = 4.U(3.W)  // rs2 ignored
  val FMAX = 5.U(3.W)
  val FMIN = 6.U(3.W)
  // 7 reserved
}

// VALU_FP_FMA (opcode=0x17): fused multiply-add, S-format (rd, rs1, rs2, rs3)
// rd = rs1 * rs2 + rs3  (FMA), etc.
object Funct3Fma {
  val FMA  = 0.U(3.W)   // rd =  (rs1 * rs2) + rs3
  val FMS  = 1.U(3.W)   // rd =  (rs1 * rs2) - rs3
  val NFMA = 2.U(3.W)   // rd = -(rs1 * rs2) + rs3
  val NFMS = 3.U(3.W)   // rd = -(rs1 * rs2) - rs3
  // 4..7 reserved
}

// VALU_MOV (opcode=0x18): register move and immediate load
object Funct3Mov {
  val MOV  = 0.U(3.W)  // R-format: rd = rs1 (copy), width from funct7[1:0]
  val MOVI = 1.U(3.W)  // I-format: rd[0] = sext(imm); other lanes unchanged
  val MOVH = 2.U(3.W)  // I-format: rd[0][31:16] = imm[15:0]; low 16 unchanged
  // 3..7 reserved
}

// MMA (opcode=0x03): systolic array matrix multiply-accumulate
object Funct3Mma {
  val MMA       = 0.U(3.W)   // normal accumulate (keep from funct7[4])
  val MMA_LAST  = 1.U(3.W)   // assert clct signal; finalize result
  val MMA_RESET = 2.U(3.W)   // clear accumulator
  // 3..7 reserved
}

// LD / ST (opcodes 0x01/0x02): memory access; funct3 encodes transfer width
object Funct3Mem {
  val BYTE  = 0.U(3.W)  // N-bit lane (byte)
  val HALF  = 1.U(3.W)  // 2N-bit
  val WORD  = 2.U(3.W)  // 4N-bit
  val VX_VEC = 3.U(3.W) // full K-lane VX vector
  val VE_VEC = 4.U(3.W) // full K-lane VE vector
  val VR_VEC = 5.U(3.W) // full K-lane VR vector
  // 6..7 reserved
}

// ---------------------------------------------------------------------------
// Backwards-compatible NeuralCoreMicroOp: wraps the raw 32-bit instruction
// word.  The InstrDecoder module unpacks it into DecodedMicroOp.
// ---------------------------------------------------------------------------
class NeuralCoreMicroOp extends Bundle {
  val word = UInt(32.W)
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  VALUMicroCode.scala — internal VALU control bundle and sub-op enums
//
//  The NCoreVALUBundle is the *decoded* view of a VALU instruction,
//  produced by InstrDecoder and consumed directly by the VALU module.
//  It is NOT the raw instruction word; see instrFormat.scala for that.
//
//  Notation: N(bits), L, K — see instSetArch.scala header.
// -----------------------------------------------------------------------------

package isa.micro_op

import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// VecDType — data-type packing layout (legacy; still used for test helpers
// and to carry the BF8 sub-format selector in the decoded bundle).
// ---------------------------------------------------------------------------
object VecDType extends ChiselEnum {
  val U8C4    = Value(0x1.U(4.W))
  val S8C4    = Value(0x2.U(4.W))
  val U16C2   = Value(0x3.U(4.W))
  val S16C2   = Value(0x4.U(4.W))
  val FP16C2  = Value(0x5.U(4.W))
  val BF16C2  = Value(0x6.U(4.W))
  val U32C1   = Value(0x7.U(4.W))
  val S32C1   = Value(0x8.U(4.W))
  val FP32C1  = Value(0x9.U(4.W))
  // FP8 formats (OCP / NVIDIA naming)
  val BF8E4M3 = Value(0xA.U(4.W))  // 1/4/3 bits; activation-side
  val BF8E5M2 = Value(0xB.U(4.W))  // 1/5/2 bits; weight/gradient-side
}

// ---------------------------------------------------------------------------
// VecOp — internal operation code decoded from opcode+funct3.
// The VALU module dispatches on this enum; it never sees raw instruction bits.
// Values are compact (5-bit) for use in MuxLookup.
// ---------------------------------------------------------------------------
object VecOp extends ChiselEnum {
  // -- ARITH (VALU_ARITH family) --
  val vadd  = Value(0x00.U(7.W))
  val vsub  = Value(0x01.U(7.W))
  val vmul  = Value(0x02.U(7.W))
  val vneg  = Value(0x03.U(7.W))
  val vabs  = Value(0x04.U(7.W))
  val vmax  = Value(0x05.U(7.W))
  val vmin  = Value(0x06.U(7.W))
  val vrsub = Value(0x07.U(7.W))

  // -- LOGIC (VALU_LOGIC family) --
  val vsll  = Value(0x08.U(7.W))
  val vsrl  = Value(0x09.U(7.W))
  val vsra  = Value(0x0A.U(7.W))
  val vrol  = Value(0x0B.U(7.W))
  val vxor  = Value(0x0C.U(7.W))
  val vnot  = Value(0x0D.U(7.W))
  val vor   = Value(0x0E.U(7.W))
  val vand  = Value(0x0F.U(7.W))

  // -- REDUCE (VALU_REDUCE family) --
  val vsum  = Value(0x10.U(7.W))
  val vrmax = Value(0x11.U(7.W))
  val vrmin = Value(0x12.U(7.W))
  val vrand = Value(0x13.U(7.W))
  val vror  = Value(0x14.U(7.W))
  val vrxor = Value(0x15.U(7.W))

  // -- LUT (VALU_LUT family) --
  // vlut   : per-lane byte lookup from a programmable 256-entry bank (bank A or B).
  //          round[0] in NCoreVALUBundle carries the bank select (0=A, 1=B).
  // vsetlut: write one K×4-byte segment of a LUT bank from a VR source register.
  //          imm in NCoreVALUBundle carries the segment index.
  //          Does NOT write to the register file; side-effect on VALU-internal state only.
  val vlut    = Value(0x18.U(7.W))
  val vsetlut = Value(0x19.U(7.W))

  // -- CVT (VALU_CVT family) — one entry per (dst_fmt, src_fmt) pair actually used --
  val vcvt_s8_s32   = Value(0x20.U(7.W))
  val vcvt_s32_s8   = Value(0x21.U(7.W))
  val vcvt_s32_f32  = Value(0x22.U(7.W))
  val vcvt_f32_s32  = Value(0x23.U(7.W))
  val vcvt_f32_s8   = Value(0x24.U(7.W))
  val vcvt_s8_f32   = Value(0x25.U(7.W))
  val vcvt_f32_bf16 = Value(0x26.U(7.W))
  val vcvt_bf16_f32 = Value(0x27.U(7.W))
  val vcvt_f32_bf8  = Value(0x28.U(7.W))
  val vcvt_bf8_f32  = Value(0x29.U(7.W))
  val vcvt_s16_s32  = Value(0x2A.U(7.W))
  val vcvt_s32_s16  = Value(0x2B.U(7.W))

  // -- BCAST (VALU_BCAST family) --
  val vbcast_reg = Value(0x30.U(7.W))
  val vbcast_imm = Value(0x31.U(7.W))

  // -- FP ARITH (VALU_FP family) --
  val vfadd = Value(0x38.U(7.W))
  val vfsub = Value(0x39.U(7.W))
  val vfmul = Value(0x3A.U(7.W))
  val vfneg = Value(0x3B.U(7.W))
  val vfabs = Value(0x3C.U(7.W))
  val vfmax = Value(0x3D.U(7.W))
  val vfmin = Value(0x3E.U(7.W))

  // -- FP FMA (VALU_FP_FMA family) --
  val vfma  = Value(0x3F.U(7.W))
  val vfms  = Value(0x40.U(7.W))
  val vnfma = Value(0x41.U(7.W))
  val vnfms = Value(0x42.U(7.W))

  // -- MOV (VALU_MOV family) --
  val vmov  = Value(0x43.U(7.W))
  val vmovi = Value(0x44.U(7.W))
  val vmovh = Value(0x45.U(7.W))
}

// ---------------------------------------------------------------------------
// NCoreVALUBundle — decoded control bundle presented to the VALU module.
// Populated by InstrDecoder; consumed by VALU.io.ctrl.
//
//   op       — internal VecOp (decoded from opcode+funct3)
//   width    — register class (VX/VE/VR), from funct7[1:0]
//   dtype    — data type / BF8 variant selector, from VecDType
//   saturate — from funct7[4]
//   round    — from funct7[3:2] (or S-type rnd field for FMA)
//   rs3_idx  — third source register (S-type only; used by FMA)
//   imm      — sign-extended 12-bit immediate (I-type only; used by bcast.imm / movi)
// ---------------------------------------------------------------------------
// NCoreVALUBundle — decoded control bundle for VALU.
//   op      : internal VecOp (decoded from opcode+funct3)
//   dtype   : data type / BF8 variant selector
//   saturate: from funct7[4]
//   round   : from funct7[3:2]; 00=RNE, 01=RTZ, 10=floor, 11=ceil
//   regCls  : register class; 0=VX (N bits), 1=VE (2N bits), 2=VR (4N bits)
//   rs3_idx : third source register (S-type / FMA)
//   imm     : sign-extended 12-bit immediate (I-type)
class NCoreVALUBundle extends Bundle {
  val op       = VecOp()
  val dtype    = VecDType()
  val saturate = Bool()
  val round    = UInt(2.W)
  val regCls   = UInt(2.W)  // 0=VX, 1=VE, 2=VR  (avoids name conflict with chisel3 Width)
  val rs3_idx  = UInt(5.W)
  val imm      = SInt(12.W)
}

// (Legacy alias — NCoreMMALUCtrlBundle stays in MMALUMicroCode.scala)

